"""Owned native Zabbix/MySQL/PHP/Agent/SMTP; never substitutes Zabbix APIs."""
import copy,gzip,hashlib,json,os,secrets,pathlib,shutil,socket,subprocess,tempfile,threading,time,urllib.request,urllib.error
PROFILE=pathlib.Path('/tmp/opsforge-session01-tools-zabbix-7.0.32');ROOT=PROFILE/'root';MYSQL=pathlib.Path('/opt/opsforge-mysql-8.4.13');MAIL=pathlib.Path('/tmp/opsforge-session01-tools-mailpit-1.27.1/mailpit')
SERVER=ROOT/'usr/sbin/zabbix_server';AGENT=ROOT/'usr/sbin/zabbix_agentd';SENDER=ROOT/'usr/bin/zabbix_sender';GET=ROOT/'usr/bin/zabbix_get';PHP=ROOT/'usr/bin/php8.3';SQL=ROOT/'usr/share/zabbix-sql-scripts/mysql/server.sql.gz';LIB=ROOT/'usr/lib/x86_64-linux-gnu';DB_NAME='opsforge_zabbix';DB_USER='opsforge_zabbix';DB_PASSWORD='OwnedZabbix2026'
PROFILE_SHA='ae1015aeaa88c24ef8e73c990aa15f2b809956af69354aed63f5e8414646747e'

def verify_profile():
 raw=(PROFILE/'runtime-profile.json').read_bytes()
 assert hashlib.sha256(raw).hexdigest()==PROFILE_SHA,'native runtime profile changed'
 profile=json.loads(raw)
 for tool in profile['tools']:assert hashlib.sha256(pathlib.Path(tool['path']).read_bytes()).hexdigest()==tool['sha256'],'native tool changed: '+tool['path']
 for row in profile['database_template_manifest']:
  path=pathlib.Path(profile['database_template'])/row['path'];assert path.stat().st_size==row['bytes'] and hashlib.sha256(path.read_bytes()).hexdigest()==row['sha256'],'native database template changed: '+row['path']
 return PROFILE_SHA

def read_json(path):return json.loads(pathlib.Path(path).read_text())
def free_port(bounded=False):
 for _ in range(100):
  with socket.socket()as sock:
   try:sock.bind(('127.0.0.1',20000+secrets.randbelow(3000)if bounded else 0));return sock.getsockname()[1]
   except OSError:pass
 raise AssertionError('No free owned loopback port in the native supported range')
def wait(fn,seconds=15):
 deadline=time.monotonic()+seconds;last=None
 while time.monotonic()<deadline:
  last=fn()
  if last:return last
  time.sleep(.1)
 raise AssertionError('Native bounded observation not satisfied: '+repr(last))
def env():return {**os.environ,'LD_LIBRARY_PATH':str(LIB)}
def http_json(url,data=None,headers=None):
 req=urllib.request.Request(url,data=None if data is None else json.dumps(data).encode(),headers={'Content-Type':'application/json',**(headers or{})})
 with urllib.request.build_opener(urllib.request.ProxyHandler({})).open(req,timeout=5)as response:return json.load(response)
def proc_identity(pid):
 try:
  p=pathlib.Path('/proc')/str(pid);text=(p/'stat').read_text().rsplit(')',1)[1].split();return {'pid':pid,'start_ticks':text[19],'state':text[0],'cwd':str((p/'cwd').resolve())}
 except(FileNotFoundError,PermissionError,ProcessLookupError):return None
def child_identities(pid):
 out=[]
 try:children=[int(x)for x in pathlib.Path('/proc/'+str(pid)+'/task/'+str(pid)+'/children').read_text().split()]
 except(FileNotFoundError,PermissionError):return out
 for child in children:
  identity=proc_identity(child)
  if identity:out.append(identity);out.extend(child_identities(child))
 return out
class Node:
 def __init__(self,owner,kind,args,directory,process_env=None):
  self.owner=owner;self.kind=kind;self.logs=[];self.stopped=False;self.args=[str(x)for x in args];self.proc=subprocess.Popen(self.args,cwd=directory,env=process_env or env(),stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True);owner.nodes.append(self);owner.commands.append({'kind':kind,'argv':self.args,'pid':self.proc.pid})
  def reader():
   for line in self.proc.stdout:
    self.logs.append(line)
    if len(self.logs)>80:self.logs.pop(0)
  self.thread=threading.Thread(target=reader,daemon=True);self.thread.start()
 def alive(self):assert self.proc.poll()is None,self.kind+' exited: '+''.join(self.logs)[-2600:]
 def stop(self):
  descendants=child_identities(self.proc.pid)
  if not self.stopped:
   if self.proc.poll()is None:
    self.proc.terminate()
    try:self.proc.wait(timeout=15)
    except subprocess.TimeoutExpired:self.proc.kill();self.proc.wait(timeout=4)
   self.thread.join(timeout=4);self.proc.stdout.close();self.stopped=True
  # Parent normally reaps its native workers. Never signal a reused or foreign PID.
  remaining=[]
  for old in descendants:
   current=proc_identity(old['pid'])
   if current and current['start_ticks']==old['start_ticks']:
    assert pathlib.Path(current['cwd']).is_relative_to(self.owner.root)
    if current['state']!='Z':os.kill(old['pid'],15)
    remaining.append(old)
  deadline=time.monotonic()+4
  while remaining and time.monotonic()<deadline:
   remaining=[x for x in remaining if (p:=proc_identity(x['pid']))and p['start_ticks']==x['start_ticks']];time.sleep(.05)
  return {'kind':self.kind,'pid':self.proc.pid,'exit_code':self.proc.returncode,'reaped':self.proc.poll()is not None,'reader_stopped':not self.thread.is_alive(),'native_children_observed':descendants,'native_children_remaining':remaining}
class Session:
 def __init__(self,bootstrap=False,with_server=True,with_mail=False):self.bootstrap=bootstrap;self.with_server=with_server;self.with_mail=with_mail
 def __enter__(self):
  assert os.getuid()==1000;verify_profile();self.before={'uid':os.getuid(),'HOME':os.environ.get('HOME'),'PATH':os.environ.get('PATH')};self.temp=tempfile.TemporaryDirectory(prefix='opsforge-s01-z016d-');self.root=pathlib.Path(self.temp.name);self.nodes=[];self.commands=[];self.api_calls=[];self.identities=[];self.token=None;self.api_id=0;self.phases=[];self.reservations={}
  try:self.start();return self
  except BaseException:self.close();raise
 def run(self,args,input=None,timeout=15):
  r=subprocess.run([str(x)for x in args],input=input,cwd=self.root,env=env(),capture_output=True,timeout=timeout);self.commands.append({'kind':'native-cli','argv':[str(x)for x in args],'exit_code':r.returncode,'stdout':r.stdout.decode(errors='replace'),'stderr':r.stderr.decode(errors='replace'),'stdin_sha256':hashlib.sha256(input).hexdigest()if input else None});return r
 def port(self,bounded=False):
  for _ in range(100):
   sock=socket.socket()
   try:sock.bind(('127.0.0.1',20000+secrets.randbelow(3000)if bounded else 0));value=sock.getsockname()[1];self.reservations[value]=sock;return value
   except OSError:sock.close()
  raise AssertionError('No free private native port')
 def release_port(self,port):self.reservations.pop(port).close()
 def sql(self,query,database=None):
  args=[MYSQL/'bin/mysql','--no-defaults','--socket='+str(self.socket),'-uroot','--batch','--raw','--skip-column-names']
  if database:args+=['--database='+database]
  result=self.run(args,input=query.encode(),timeout=600 if len(query)>10000 else 30);assert result.returncode==0,result.stderr.decode(errors='replace');return result.stdout.decode()
 def php_args(self):
  args=[str(PHP),'-n','-d','extension_dir='+str(ROOT/'usr/lib/php/20230831')]
  for module in ['mysqlnd','mysqli','bcmath','ctype','mbstring','gd','xml','dom','simplexml','xmlreader','xmlwriter','sockets','gettext']:args+=['-d','extension='+module]
  for setting in ['date.timezone=UTC','memory_limit=256M','max_execution_time=60','post_max_size=32M','upload_max_filesize=32M','session.save_path='+str(self.root),'sys_temp_dir='+str(self.root)]:args+=['-d',setting]
  return args
 def start(self):
  self.data=self.root/'mysql-data';self.socket=self.root/'mysql.sock';self.mysql_port=self.port();self.server_port=self.port(True);self.php_port=self.port();self.agent_port=self.port(True);self.front=self.root/'frontend'
  if self.bootstrap:
   args=[MYSQL/'bin/mysqld','--no-defaults','--initialize-insecure','--basedir='+str(MYSQL),'--datadir='+str(self.data),'--innodb-redo-log-capacity=16777216','--innodb-buffer-pool-size=134217728','--log-error='+str(self.root/'initialize.log')];r=self.run(args,timeout=100);self.commands.append({'kind':'mysql-initialize','argv':[str(x)for x in args],'exit_code':r.returncode});assert r.returncode==0,(r.stderr.decode(errors='replace'),(self.root/'initialize.log').read_text()[-2500:])
  else:
   baseline=PROFILE/'db-template';assert baseline.is_dir(),'pinned initialized native database template is not prepared';shutil.copytree(baseline,self.data)
  args=[MYSQL/'bin/mysqld','--no-defaults','--basedir='+str(MYSQL),'--datadir='+str(self.data),'--socket='+str(self.socket),'--port='+str(self.mysql_port),'--bind-address=127.0.0.1','--mysqlx=0','--skip-log-bin','--innodb-flush-log-at-trx-commit=2','--innodb-doublewrite=OFF','--pid-file='+str(self.root/'mysqld.pid'),'--log-error='+str(self.root/'mysql.log'),'--innodb-redo-log-capacity=16777216','--innodb-buffer-pool-size=134217728','--secure-file-priv='+str(self.root)]
  self.release_port(self.mysql_port);self.mysql=Node(self,'mysql',args,self.root)
  def db_ready():
   self.mysql.alive()
   if not self.socket.exists():return False
   r=self.run([MYSQL/'bin/mysql','--no-defaults','--socket='+str(self.socket),'-uroot','-Nse','SELECT 1']);return r.returncode==0
  try:wait(db_ready,40)
  except AssertionError as exc:raise AssertionError(str(exc)+'; mysql log='+((self.root/'mysql.log').read_text()[-2200:]if(self.root/'mysql.log').exists()else''))from exc
  assert pathlib.Path(self.sql('SELECT @@datadir').strip()).resolve()==self.data.resolve();self.root_auth_before=self.sql("SELECT User,Host,plugin,authentication_string FROM mysql.user WHERE User='root'")
  if self.bootstrap:
   self.sql('CREATE DATABASE '+DB_NAME+" CHARACTER SET utf8mb4 COLLATE utf8mb4_bin; CREATE USER '"+DB_USER+"'@'localhost' IDENTIFIED BY '"+DB_PASSWORD+"'; GRANT ALL PRIVILEGES ON "+DB_NAME+".* TO '"+DB_USER+"'@'localhost';");self.sql(gzip.decompress(SQL.read_bytes()).decode(),DB_NAME)
  shutil.copytree(ROOT/'usr/share/zabbix',self.front,symlinks=True)
  conf=self.front/'conf'
  if conf.is_symlink():assert conf.parent.resolve().is_relative_to(self.root);conf.unlink();conf.mkdir()
  conf.mkdir(exist_ok=True);config_path=conf/'zabbix.conf.php'
  if config_path.is_symlink():assert config_path.parent.resolve().is_relative_to(self.root);config_path.unlink()
  config="<?php\n$DB['TYPE'] = 'MYSQL';\n$DB['SERVER'] = '127.0.0.1';\n$DB['PORT'] = "+str(self.mysql_port)+";\n$DB['DATABASE'] = '"+DB_NAME+"';\n$DB['USER'] = '"+DB_USER+"';\n$DB['PASSWORD'] = '"+DB_PASSWORD+"';\n$DB['SCHEMA'] = '';\n$DB['ENCRYPTION'] = false;\n$ZBX_SERVER = '127.0.0.1';\n$ZBX_SERVER_PORT = "+str(self.server_port)+";\n$ZBX_SERVER_NAME = 'OpsForge owned validation';\n$IMAGE_FORMAT_DEFAULT = IMAGE_FORMAT_PNG;\n";config_path.write_text(config);config_path.chmod(0o600)
  self.endpoint='http://127.0.0.1:'+str(self.php_port)+'/api_jsonrpc.php';self.release_port(self.php_port);self.php=Node(self,'php',self.php_args()+['-S','127.0.0.1:'+str(self.php_port),'-t',str(self.front)],self.root)
  def api_ready():
   self.php.alive()
   try:return http_json(self.endpoint,{'jsonrpc':'2.0','method':'apiinfo.version','params':{},'id':1}).get('result')=='7.0.32'
   except(urllib.error.URLError,ValueError,TimeoutError):return False
  try:wait(api_ready,15)
  except AssertionError as exc:raise AssertionError(str(exc)+'; php logs='+''.join(self.php.logs)[-3000:])from exc
  self.token=self.api('user.login',{'username':'Admin','password':'zabbix'},authenticated=False);self.identities.append({'stage':'before','default_admin_login_preserved':True})
  if self.bootstrap:
   defaults=self.api('host.get',{'output':['hostid','host','status']})
   for host in defaults:
